/*:
 * @target MV MZ
 * @plugindesc Add left/right = page up/down for Show Choices.
 * @author Caethyril
 * @url https://forums.rpgmakerweb.com/threads/172940/
 * @help Free to use and/or modify for any project, no credit required.
 */
// Override - redirect cursor left/right to page up/down on trigger
Window_ChoiceList.prototype.cursorLeft = function(triggered) {
    if (triggered) this.cursorPageup();
};
Window_ChoiceList.prototype.cursorRight = function(triggered) {
    if (triggered) this.cursorPagedown();
};
